package main

import (
	"fmt"
	"maps"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
)

// Generated launchers resolve their own location first. PATH is reset so a
// wrapper can not end up calling itself in a loop.
const header = `#!/bin/bash
# Generated by tykky. Runs a command from the installation inside its container.
# The setup shared by all wrappers comes first, then the command to run.

export OLD_PATH=$PATH
export PATH="/usr/local/bin:/usr/bin:/usr/local/sbin:/usr/sbin:/bin"
# a wrapper passes the path it was called by, for argv0 and venv detection
SOURCE="${_CW_SOURCE:-${BASH_SOURCE[0]}}"
unset _CW_SOURCE
_O_SOURCE=$SOURCE
# ${SOURCE%/*} below is dirname, which needs a slash in SOURCE
[[ $SOURCE == */* ]] || SOURCE=./$SOURCE
_venvd=${SOURCE%/*}
# resolve $SOURCE until the file is no longer a symlink
while [ -h "$SOURCE" ]; do
    DIR="$(cd -P "${SOURCE%/*}" >/dev/null 2>&1 && pwd)"
    SOURCE="$(command -p readlink "$SOURCE")"
    # a relative symlink is resolved relative to the directory holding it
    [[ $SOURCE != /* ]] && SOURCE="$DIR/$SOURCE"
done
DIR="$(cd -P "${SOURCE%/*}" >/dev/null 2>&1 && pwd)"
`

// probe runs a command inside the built container and returns its stdout.
func (b *build) probe(args ...string) (string, error) {
	c := b.c
	pre := []string{"--silent", "exec"}
	if c.get("mode") != modeWrapCont {
		pre = append(pre, "-B", imageBind(b.sqfs(), c.get("installation_path")))
	}
	cmd := b.cmd(nil, b.sing, append(append(pre, b.img()), args...)...)
	cmd.Stdout, cmd.Stderr = nil, nil
	out, err := cmd.Output()
	return string(out), err
}

var libDir = regexp.MustCompile(`lib[64]*$`)

// shq quotes s as a single shell word.
func shq(s string) string { return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'" }

func shqAll(l []string) string {
	q := make([]string, len(l))
	for i, s := range l {
		q[i] = shq(s)
	}
	return strings.Join(q, " ")
}

// dq escapes s for use inside double quotes, keeping $VAR expansion.
func dq(s string) string { return strings.NewReplacer(`\`, `\\`, `"`, `\"`).Replace(s) }

// The wrappers pass these through bash -c "...", so they are quoted again for the inner shell.
const qSrc, qDir, qCmd = `$(printf %q "$_O_SOURCE")`, `$(printf %q "$DIR")`, `$(printf %q "$_cmd")`

// stub is a wrapper: it finds _containerize_exec next to itself, also when
// called through a venv symlink, and hands it the command and arguments.
const stub = `#!/bin/bash
# Generated by tykky. Runs %s in the container, see _containerize_exec.
_r=$(command -p readlink -f "${BASH_SOURCE[0]}")
_CW_SOURCE=${BASH_SOURCE[0]} exec "${_r%%/*}/_containerize_exec" %s "$@"
`

func (b *build) wrappers() error {
	c, d := b.c, b.deploy
	isolate, wrapcont := c.yes("isolate"), c.get("mode") == modeWrapCont
	ipath := c.get("installation_path")
	if err := os.MkdirAll(d+"/bin", 0o777); err != nil {
		return err
	}
	if err := os.MkdirAll(d+"/_bin", 0o777); err != nil {
		return err
	}
	var w strings.Builder
	pr := func(f string, a ...any) { fmt.Fprintf(&w, f, a...) }

	runCmd := shq(b.sing) + ` --silent exec "$DIR/../$CONTAINER_IMAGE"`
	shellCmd := shq(b.sing) + ` --silent shell "$DIR/../$CONTAINER_IMAGE"`
	pr("\n# set up the container: the image to run, the host directories to bind into it and its environment\nshopt -s extglob\n")
	if !wrapcont {
		pr("SQFS_IMAGE=%s\n", shq(c.get("sqfs_image")))
	}
	pr("_C_DIR=\"$(cd \"$DIR/..\" >/dev/null 2>&1 && pwd)\"\nCONTAINER_IMAGE=%s\nINSTALLATION_PATH=%s\n\n", shq(c.get("container_image")), shq(ipath))
	if c.has("wrapper_ld_library_paths") {
		pr("export SINGULARITYENV_LD_LIBRARY_PATH=\"$SINGULARITYENV_LD_LIBRARY_PATH:\"%s\n", shq(strings.Join(c.list("wrapper_ld_library_paths"), ":")))
	}
	if isolate {
		pr("# isolated: bind only these host directories and use the container's own paths\n")
		pr("_DIRS=(%s)\n", strings.TrimSpace(shqAll(c.list("mount_points"))+` "$_C_DIR"`))
		out, _ := b.probe("sh", "-c", "echo $PATH; echo $LD_LIBRARY_PATH")
		path, ld, _ := strings.Cut(out, "\n")
		pr(`SINGULARITYENV_DEFAULT_PATH=%s
SINGULARITYENV_DEFAULT_LD_LIBRARY_PATH=%s
export SINGULARITYENV_PATH="$SINGULARITYENV_PATH:$SINGULARITYENV_DEFAULT_PATH"
export SINGULARITYENV_LD_LIBRARY_PATH="$SINGULARITYENV_LD_LIBRARY_PATH:$SINGULARITYENV_DEFAULT_LD_LIBRARY_PATH"
`, shq(strings.TrimSpace(path)), shq(strings.TrimSpace(ld)))
	} else {
		// the launch time version of rootDirs in build.go
		pr(`# bind all top level host directories except device ones, keep the host paths
_DIRS=()
for d in /*; do
    [[ $d == *dev* ]] || _DIRS+=("$d")
done
export SINGULARITYENV_PATH="$OLD_PATH"
export SINGULARITYENV_LD_LIBRARY_PATH="$SINGULARITYENV_LD_LIBRARY_PATH:$LD_LIBRARY_PATH"
`)
		if c.has("excluded_mount_points") {
			pr(`_excludes=(%s)
for mp in "${_excludes[@]}"; do
    _DIRS=("${_DIRS[@]/$mp}")
done
`, shqAll(c.list("excluded_mount_points")))
		}
	}
	pr(`
# already inside a container: check that it is ours
if [[ $(</proc/self/mountinfo) =~ (singularity|apptainer)/mnt/session ]]; then
    export _CW_IN_CONTAINER=Yes
    if [[ %[1]s == "yes" && ! "$SINGULARITY_CONTAINER" -ef "$_C_DIR/$CONTAINER_IMAGE" ]]; then
        echo "[ ERROR ] wrapper called from another container. Is $SINGULARITY_CONTAINER, should be $_C_DIR/$CONTAINER_IMAGE "
        exit 1
    fi
    if [[ ! -e %[2]s ]]; then
        echo "[ ERROR ] Installation for $_C_DIR/ is not mounted. Wrapper called from another container?"
        exit 1
    fi
else
    unset _CW_IN_CONTAINER
    export _CW_IS_ISOLATED=%[1]s
fi

# settings left over from another container must not leak into ours
if [[ ! ${_CW_IN_CONTAINER+defined} && ${SINGULARITY_NAME+defined} ]]; then
    unset {SINGULARITY,APPTAINER}_{NAME,COMMAND,ENVIRONMENT,BIND,CONTAINER}
fi

# bind the directories that exist, $TMPDIR as /tmp and the wrapper directories
for d in "${_DIRS[@]}"; do
    if [[ -z "$SINGULARITY_BIND" ]]; then
        test -d "$d" && export SINGULARITY_BIND="$d"
    else
        test -d "$d" && export SINGULARITY_BIND="$SINGULARITY_BIND,$d"
    fi
done
if [[ "${TMPDIR+defined}" ]]; then
    SINGULARITY_BIND="$SINGULARITY_BIND,$TMPDIR,$TMPDIR:/tmp"
fi
SINGULARITY_BIND="$SINGULARITY_BIND,$(cd -P "$_C_DIR/_bin" && pwd):$(cd -P "$_C_DIR/bin" && pwd)"
`, shq(yesno(isolate)), shq(ipath))
	// cd -P above: on LUMI some folders are symlinks to lustre mount points
	if wrapcont {
		pr("export SINGULARITY_BIND\n")
	} else {
		pr("export SINGULARITY_BIND=$SINGULARITY_BIND,%s\n", imageBind("$DIR/../$SQFS_IMAGE", "$INSTALLATION_PATH"))
	}
	pr(`# user supplied extra binds, except image mounts onto the installation path
if [[ ${CW_EXTRA_BIND_MOUNTS+defined} && %s == "no" ]]; then
    export SINGULARITY_BIND=$SINGULARITY_BIND,${CW_EXTRA_BIND_MOUNTS//*([^,]):"$INSTALLATION_PATH":image-src=\//}
fi
`, shq(yesno(isolate)))

	info(1, "Creating wrappers")
	defaultCws := `bash -c "`
	if v, _ := b.probe("bash", "--version"); v == "" && isolate { // the container may lack bash
		info(1, "Using sh inside the container as bash was not found")
		defaultCws = `sh -c "`
	}
	// printf %q keeps the arguments quoted as given; the test avoids passing '' when there are none
	const cwe = `$(test $# -eq 0 || printf " %q" "$@")"`
	var libPaths []string
	// written once the shared setup in w is complete
	bodies, stubs := map[string]string{}, map[string]string{}
	// the bash -c prefix of each command, which carries its conda activation
	cmdCws := map[string]string{}
	wrapperPaths := c.list("wrapper_paths")
	if r := b.envRoot(); r != "" {
		wrapperPaths = append(wrapperPaths, r+"bin/")
	}
	skip := c.list("excluded_wrappers")
	for _, wp := range wrapperPaths {
		cws := defaultCws
		info(2, "Generating wrappers for %s", wp)
		var targets []string
		if _, err := b.probe("test", "-f", wp); err == nil {
			targets, wp = []string{path.Base(wp)}, path.Dir(wp)
		} else {
			ls, _ := b.probe("ls", "-F", wp)
			for _, t := range strings.Fields(ls) {
				kind, name := t[len(t)-1], t
				if strings.ContainsRune("*@|=/", rune(kind)) {
					name = t[:len(t)-1]
				}
				if (kind == '*' || kind == '@' || c.yes("wrap_all") && kind != '/') && !slices.Contains(skip, name) {
					targets = append(targets, name)
				}
			}
			if c.yes("add_ld") {
				parent, _ := b.probe("ls", wp+"/..")
				for _, l := range strings.Fields(parent) {
					if libDir.MatchString(l) {
						libPaths = append(libPaths, path.Dir(path.Clean(wp))+"/"+l)
					}
				}
			}
			if len(targets) == 0 {
				// no way to remove wrapper paths when updating, so don't fail
				warn("Path %s does not exist in container or is empty \n\tif only wrapping executables, did you forget +x?", wp)
				continue
			}
			if _, err := b.probe("test", "-f", wp+"/../../../bin/conda"); err == nil {
				info(3, "Inserting conda activation into wrappers")
				cws = fmt.Sprintf(`bash -c "eval \"\$(%s shell.bash hook)\" && conda activate %s &>/dev/null && `,
					shq(path.Clean(wp+"/../../../bin/conda")), shq(path.Base(path.Clean(wp+"/.."))))
			}
		}
		for _, t := range targets {
			info(3, "Creating wrapper for %s", t)
			if _, ok := stubs[t]; ok {
				warn("Multiple binaries with the same name")
				os.Remove(d + "/_bin/" + t)
			}
			if err := os.Symlink(wp+"/"+t, d+"/_bin/"+t); err != nil {
				return err
			}
			stubs[t], cmdCws[t] = fmt.Sprintf(stub, t, shq(t)), cws
			if t == "python" {
				if err := b.venvLinks(wp); err != nil {
					return err
				}
			}
		}
	}

	groups := map[string][]string{}
	for t, cws := range cmdCws {
		groups[cws] = append(groups[cws], shq(t))
	}
	var arms strings.Builder
	// sorted for stable output; commands without conda go to the default arm, last
	for _, cws := range slices.Sorted(maps.Keys(groups)) {
		if cws == defaultCws {
			continue
		}
		slices.Sort(groups[cws])
		fmt.Fprintf(&arms, `%[8]s)
    # activate the conda environment, unless running from a venv made on top of it
    test -e "$_venvd/../pyvenv.cfg"
    _v_in_use=$?
    if [[ ( $_v_in_use -eq 0 && ! ${CW_FORCE_CONDA_ACTIVATE+defined} ) || ${CW_NO_CONDA_ACTIVATE+defined} ]]; then
        %[1]s %[2]sexec -a %[6]s %[7]s/%[3]s %[4]s
    else
        _venv_act=":"
        test 0 -eq $_v_in_use && _venv_act="source $(printf %%q "$_venvd")/activate"
        %[1]s %[5]s$_venv_act && exec -a %[6]s %[7]s/%[3]s %[4]s
    fi
    ;;
`, runCmd, defaultCws, qCmd, cwe, cws, qSrc, qDir, strings.Join(groups[cws], "|"))
	}
	if _, ok := groups[defaultCws]; ok {
		fmt.Fprintf(&arms, "*)\n    %s %sexec -a %s %s/%s %s\n    ;;\n", runCmd, defaultCws, qSrc, qDir, qCmd, cwe)
	}
	bodies["_containerize_exec"] = fmt.Sprintf(`
# the first argument is the wrapped command to run, the rest are its arguments
_cmd=$1
shift
if [[ -z $_cmd || $_cmd == */* || ! -L "$DIR/../_bin/$_cmd" ]]; then
    echo "[ ERROR ] '$_cmd' is not a command wrapped by this installation" >&2
    exit 1
fi
export PATH="$OLD_PATH"
# inside the container run it directly, otherwise start the container for it
if [[ ${_CW_IN_CONTAINER+defined} ]]; then
    exec -a "$_O_SOURCE" "$DIR/../_bin/$_cmd" "$@"
fi
case $_cmd in
%sesac
`, arms.String())

	debug := map[string][2]string{"_debug_shell": {shellCmd, "open a shell"}, "_debug_exec": {runCmd, "run a command"}}
	for name, run := range debug {
		bodies[name] = fmt.Sprintf("\n# for debugging: %s in the container, with the same setup as the wrappers\nif [[ -z \"$SINGULARITY_NAME\" ]]; then\n    %s \"$@\"\nfi\n", run[1], run[0])
	}

	if len(libPaths) > 0 {
		pr("SINGULARITYENV_LD_LIBRARY_PATH=%s\":$SINGULARITYENV_LD_LIBRARY_PATH\"\n", shq(strings.Join(libPaths, ":")))
	}
	pr(`# drop empty entries from the paths
for v in SINGULARITYENV_PATH SINGULARITYENV_LD_LIBRARY_PATH; do
    _p=":${!v}:"
    while [[ $_p == *::* ]]; do _p=${_p//::/:}; done
    _p=${_p#:}
    printf -v "$v" %%s "${_p%%:}"
done
`)
	if wrapcont {
		pr(`# a venv made on top of the wrapped container should keep finding its own python
test -e "$_venvd/../pyvenv.cfg"
_v_in_use=$?
[[ $_v_in_use -eq 0 ]] && _py=$(command -p readlink -f "$_venvd/python") && [[ "${_py%%/*}" == "$(cd -P "$_C_DIR/bin" && pwd)" ]] && SINGULARITYENV_PATH="$(cd -P "$_venvd" >/dev/null && pwd):$SINGULARITYENV_PATH"
`)
	} else {
		pr("export install_root=%s\n", shq(ipath))
		if r := b.envRoot(); r != "" {
			pr("export env_root=%s\n", shq(r))
		}
	}
	for _, e := range list(c["extra_envs"]) {
		m, _ := e.(map[string]any)
		if f, ok := m["file"]; ok {
			s, err := os.ReadFile(str(f))
			if err != nil {
				return err
			}
			w.Write(s)
			continue
		}
		name, val := str(m["name"]), dq(str(m["value"]))
		switch str(m["type"]) {
		case "set":
			pr("export %s=\"%s\"\n", name, val)
		case "append":
			pr("export %s=\"$%s:%s\"\n", name, name, val)
		default:
			pr("export %s=\"%s:$%s\"\n", name, val, name)
		}
	}
	for name, body := range bodies {
		if err := os.WriteFile(d+"/bin/"+name, []byte(header+w.String()+body), 0o777); err != nil {
			return err
		}
	}
	for name, s := range stubs {
		if err := os.WriteFile(d+"/bin/"+name, []byte(s), 0o777); err != nil {
			return err
		}
	}
	return os.Chmod(d, statPerm(d)|0o005)
}

// venvLinks makes the installation look like the venv it wraps, so that
// venvs created from the wrapped python work.
func (b *build) venvLinks(wp string) error {
	info(2, "Found python, checking if venv")
	cfg, err := b.probe("cat", wp+"/../pyvenv.cfg")
	if err != nil {
		return nil
	}
	info(2, "Target is a venv")
	if err := os.WriteFile(b.deploy+"/pyvenv.cfg", []byte(cfg), 0o666); err != nil {
		return err
	}
	found, _ := b.probe("find", wp+"/../lib", "-maxdepth", "1", "-type", "d", "-regex", `.*/python[0-9]+\.[0-9]+$`)
	pyd := filepath.Base(strings.TrimSpace(found))
	if err := os.MkdirAll(b.deploy+"/lib/"+pyd, 0o777); err != nil {
		return err
	}
	if err := os.Symlink(wp+"/../lib/"+pyd+"/site-packages", b.deploy+"/lib/"+pyd+"/site-packages"); err != nil && !os.IsExist(err) {
		return err
	}
	if err := os.Symlink("lib", b.deploy+"/lib64"); err != nil && !os.IsExist(err) {
		return err
	}
	return nil
}
